const stationOperatorCandidates = `-- name: StationOperatorCandidates :many
SELECT u.id, u.display_name,
       (p.user_id IS NOT NULL)::boolean AS has_pin,
       (b.user_id IS NOT NULL)::boolean AS has_badge
FROM identity.users u
CROSS JOIN LATERAL (
    SELECT EXISTS (
        SELECT 1
        FROM identity.user_roles ur
        JOIN identity.roles r ON r.id = ur.role_id
        WHERE ur.user_id = u.id AND r.name = 'Owner'
    ) AS is_owner
) o
LEFT JOIN identity.scim_user_mappings m ON m.user_id = u.id
LEFT JOIN identity.user_pins p ON p.user_id = u.id
LEFT JOIN identity.user_badges b ON b.user_id = u.id
WHERE NOT u.is_disabled
  AND u.kind = 'person'
  AND u.pending_since IS NULL
  AND (p.user_id IS NOT NULL OR b.user_id IS NOT NULL)
  AND (NOT $1::boolean OR m.upstream_active IS NOT FALSE OR o.is_owner)
  AND (o.is_owner OR EXISTS (
      SELECT 1
      FROM identity.role_permissions rp
      WHERE rp.permission_key = $2
        AND rp.role_id IN (
            SELECT ur.role_id
            FROM identity.user_roles ur
            WHERE ur.user_id = u.id
            UNION
            SELECT gm_map.role_id
            FROM identity.access_group_memberships gm
            JOIN identity.access_groups g ON g.id = gm.group_id AND g.is_active
            JOIN identity.access_group_role_mappings gm_map ON gm_map.group_id = g.id AND gm_map.source = g.source
            WHERE gm.user_id = u.id
              AND (gm.membership_override = 'force_member'
                   OR (gm.membership_override IS NULL AND gm.is_upstream_present))
        )
  ))
ORDER BY u.display_name, u.id
`

type StationOperatorCandidatesParams struct {
	ScimEnabled   bool
	PermissionKey string
}

type StationOperatorCandidatesRow struct {
	ID          uuid.UUID
	DisplayName string
	HasPin      bool
	HasBadge    bool
}

// StationOperatorCandidates is who may switch in at a station: the active
// people holding permission_key (DirectoryPermissionHolders' rule) who have a
// PIN or a badge.
func (q *Queries) StationOperatorCandidates(ctx context.Context, arg StationOperatorCandidatesParams) ([]StationOperatorCandidatesRow, error) {
	rows, err := q.db.Query(ctx, stationOperatorCandidates, arg.ScimEnabled, arg.PermissionKey)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StationOperatorCandidatesRow
	for rows.Next() {
		var i StationOperatorCandidatesRow
		if err := rows.Scan(
			&i.ID,
			&i.DisplayName,
			&i.HasPin,
			&i.HasBadge,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

